const saveReservationSettings = `-- name: SaveReservationSettings :one
UPDATE reservation_settings
SET enabled = $1, duration_min = $2, large_party_size = $3, large_duration_min = $4,
    hold_before_min = $5, grace_min = $6, release_after_min = $7, updated_at = now()
WHERE id
RETURNING id, enabled, duration_min, large_party_size, large_duration_min, hold_before_min, grace_min, release_after_min, updated_at
`

type SaveReservationSettingsParams struct {
	Enabled          bool  `json:"enabled"`
	DurationMin      int32 `json:"duration_min"`
	LargePartySize   int32 `json:"large_party_size"`
	LargeDurationMin int32 `json:"large_duration_min"`
	HoldBeforeMin    int32 `json:"hold_before_min"`
	GraceMin         int32 `json:"grace_min"`
	ReleaseAfterMin  int32 `json:"release_after_min"`
}

func (q *Queries) SaveReservationSettings(ctx context.Context, arg SaveReservationSettingsParams) (ReservationSetting, error) {
	row := q.db.QueryRow(ctx, saveReservationSettings,
		arg.Enabled,
		arg.DurationMin,
		arg.LargePartySize,
		arg.LargeDurationMin,
		arg.HoldBeforeMin,
		arg.GraceMin,
		arg.ReleaseAfterMin,
	)
	var i ReservationSetting
	err := row.Scan(
		&i.ID,
		&i.Enabled,
		&i.DurationMin,
		&i.LargePartySize,
		&i.LargeDurationMin,
		&i.HoldBeforeMin,
		&i.GraceMin,
		&i.ReleaseAfterMin,
		&i.UpdatedAt,
	)
	return i, err
}

